<script setup>
import {ref,watch} from 'vue';
import DiagnosticCriteriaComparison from './DiagnosticCriteriaComparison.vue';
const props=defineProps({agencyId:[Number,String],clientId:[Number,String],noteId:[Number,String],transport:Object});
async function client(){return props.transport || (await import('../../services/api.js')).default;}
const reviews=ref([]);let generation=0;
async function load(){const current=++generation;reviews.value=[];if(!props.agencyId || !props.clientId)return;try{const {data}=await (await client()).get(props.transport?`/clients/${props.clientId}/diagnosis-criteria`:`/narriva/clients/${props.clientId}/diagnosis-criteria`,{params:{agencyId:props.agencyId,noteId:props.noteId || undefined},skipGlobalLoading:true});if(current===generation)reviews.value=data.reviews || [];}catch{ /* An optional aid must not interrupt ordinary chart review. */ }}
watch(()=>[props.agencyId,props.clientId,props.noteId],load,{immediate:true});
</script>
<template><section v-if="reviews.length" class="internal-criteria" data-internal-review-only aria-label="Internal diagnostic support review"><header><strong>Internal diagnostic support review</strong><span>Excluded from medical-record downloads</span></header><article v-for="item in reviews" :key="item.id"><div class="criteria-summary" :class="{incomplete:item.summary?.status!=='supported'}"><strong>{{item.code}}</strong><span>{{item.summary?.message || 'Criteria support unconfirmed'}}</span></div><p v-if="item.summary?.status!=='supported'">Review the documented symptoms and required clinical parameters alongside the diagnostic justification.</p><details><summary>Review symptoms and parameters</summary><p>{{item.message}}</p><DiagnosticCriteriaComparison :criteria="item.criteria || []" /></details></article></section></template>
<style scoped>.internal-criteria{border:1px solid #e4ca83;border-left:4px solid #c39529;border-radius:9px;padding:14px;margin:14px 0;background:#fffaf0;color:#604b20;font-size:13px}.internal-criteria header{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}.internal-criteria header span{font-size:11px}.internal-criteria article{border-top:1px solid #ebdfbd;padding-top:10px;margin-top:10px}.criteria-summary{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.criteria-summary.incomplete span{font-weight:650;background:#ffedb5;padding:5px 8px;border-radius:5px}.internal-criteria p,.internal-criteria li{font-size:12px;line-height:1.6}.internal-criteria summary{cursor:pointer;font-weight:600}@media print{.internal-criteria{display:none!important}}</style>
